# Generated by build.py from recipe.yml for recipe imap-start-a-mailbox-with-folders. Do not edit.
set -e
cd "$(dirname "$0")"
awk '{printf "%s\r\n", $0}' > sent.eml <<'EOF'
From: ann@example.com
To: bob@example.com
Subject: Minutes

The minutes are attached.
EOF
surl --mail-domain example.com --mailbox "ann@example.com:annpass;folders=Sent,Drafts,Archive" --mailbox "bob@example.com:bobpass;folders=Sent,Drafts,Archive" --mailbox carol@example.com:carolpass --mailbox "dave@example.com:davepass;folders=Sent Items,Archive/2026" --mailbox "erin@example.com:erinpass;folders=Paid%2CUnpaid" imap://127.0.0.1:8080/ &
sleep 1
curl -u ann@example.com:annpass imap://127.0.0.1:8080/
kill $(jobs -p)
